/**
 * M11 — dispatch and trips repository.
 *
 * Tenant scoping is explicit in every statement and also enforced by PostgreSQL RLS.
 * All timestamps are generated by the database (`now()`); no client timestamp is accepted.
 * Status changes are append-only trip_events, written by the database trigger.
 */
import {
  cycleMinutes,
  dispatchKpis,
  isTerminalTripStatus,
  isWaitFlagged,
  nextTripStatus,
  OPEN_TRIP_STATUSES,
  siteWaitMinutes,
  tripGroup,
  type DispatchTripStatus,
  type TripGroup,
} from '../../src/core/dispatch';
import { MIN_OVERRIDE_REASON } from '../../src/core/rules';
import type { Db, Executor } from '../db/client';
import { M1Error } from './m1';
import type { B1Context } from './projects';

type Row = Record<string, unknown>;

const str = (value: unknown): string => (value === null || value === undefined ? '' : String(value));
const nullable = (value: unknown): string | null =>
  value === null || value === undefined ? null : String(value);
const num = (value: unknown): number => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
};
const numOrNull = (value: unknown): number | null => {
  if (value === null || value === undefined || value === '') return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
};

/** PostgreSQL returns dates as Date objects; the API contract is ISO text. */
const dateOnly = (value: unknown): string => {
  if (value === null || value === undefined) return '';
  if (value instanceof Date) return value.toISOString().slice(0, 10);
  const text = String(value);
  const parsed = new Date(text);
  return Number.isNaN(parsed.getTime()) ? text.slice(0, 10) : parsed.toISOString().slice(0, 10);
};

const isoDateTime = (value: unknown): string | null => {
  if (value === null || value === undefined) return null;
  if (value instanceof Date) return value.toISOString();
  const text = String(value);
  const parsed = new Date(text);
  return Number.isNaN(parsed.getTime()) ? text : parsed.toISOString();
};

const newId = (prefix: string): string =>
  `${prefix}-${crypto.randomUUID().replace(/-/g, '').slice(0, 10).toUpperCase()}`;

const todayCairo = (): string =>
  new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Africa/Cairo',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(new Date());

const ACCEPTED_ORDER_STATUSES = ['confirmed', 'scheduled', 'in_production'] as const;

const TRIP_SELECT = `
  select tr.id, tr.company_id, tr.plant_id, tr.order_id, tr.customer_id, tr.truck_id,
         tr.assignment_id, tr.driver_name, tr.mix_design_id,
         tr.target_m3::text as target_m3, tr.loaded_m3::text as loaded_m3,
         tr.loaded_volume_m3::text as loaded_volume_m3,
         tr.status, tr.departure_time, tr.departed_at, tr.arrive_site_time,
         tr.finish_unload_time, tr.return_time, tr.returned_at,
         tr.wait_min_at_site, tr.site_wait_minutes, tr.cancel_reason, tr.aborted_reason,
         tr.trip_date, tr.created_at, tr.created_by, tr.updated_at,
         o.order_no, o.concrete_grade, o.status as order_status,
         c.name_ar as customer_name_ar, c.name_en as customer_name_en,
         p.name_ar as project_name_ar, p.name_en as project_name_en,
         tk.plate_no as truck_plate, tk.capacity_m3::text as truck_capacity_m3,
         md.code as mix_code, md.name_ar as mix_name_ar, md.name_en as mix_name_en,
         (select max(e.created_at) from trip_events e
           where e.company_id = tr.company_id and e.trip_id = tr.id) as stage_started_at
    from trips tr
    left join orders o on o.id = tr.order_id and o.company_id = tr.company_id
    left join customers c on c.id = tr.customer_id and c.company_id = tr.company_id
    left join projects p on p.id = o.project_id and p.company_id = tr.company_id
    left join trucks tk on tk.id = tr.truck_id and tk.company_id = tr.company_id
    left join mix_designs md on md.id = tr.mix_design_id and md.company_id = tr.company_id
   where tr.company_id = $1`;

export interface DispatchTripRow {
  id: string;
  company_id: string;
  plant_id: string;
  order_id: string | null;
  customer_id: string | null;
  truck_id: string | null;
  driver_name: string;
  mix_design_id: string | null;
  target_m3: number;
  loaded_m3: number | null;
  status: DispatchTripStatus;
  departure_time: string | null;
  arrive_site_time: string | null;
  finish_unload_time: string | null;
  return_time: string | null;
  wait_min_at_site: number | null;
  wait_flagged: boolean;
  cycle_minutes: number | null;
  site_wait_minutes: number | null;
  stage_started_at: string | null;
  stage_elapsed_minutes: number | null;
  cancel_reason: string;
  trip_date: string;
  created_at: string;
  order_no: string;
  concrete_grade: string;
  order_status: string;
  customer_name_ar: string;
  customer_name_en: string;
  project_name_ar: string;
  project_name_en: string;
  truck_plate: string;
  truck_capacity_m3: number | null;
  mix_code: string;
  mix_name_ar: string;
  mix_name_en: string;
  group: TripGroup;
}

export interface DispatchTruckRow {
  id: string;
  plant_id: string;
  plate_no: string;
  capacity_m3: number;
  status: string;
  current_odometer: number | null;
  active: boolean;
  trips_today: number;
  m3_today: number;
}

export interface DispatchOrderRow {
  id: string;
  plant_id: string | null;
  order_no: string;
  customer_id: string;
  customer_name_ar: string;
  customer_name_en: string;
  project_id: string | null;
  project_name_ar: string;
  project_name_en: string;
  concrete_grade: string;
  quantity_m3: number;
  assigned_m3: number;
  remaining_m3: number;
  status: string;
  delivery_date: string;
  order_date: string;
}

export interface DispatchMixRow {
  id: string;
  plant_id: string;
  code: string;
  name_ar: string;
  name_en: string;
}

export interface DispatchPlantRow {
  id: string;
  name_ar: string;
  name_en: string;
}

export interface DispatchBoard {
  date: string;
  trips: DispatchTripRow[];
  trucks: DispatchTruckRow[];
  orders: DispatchOrderRow[];
  mixDesigns: DispatchMixRow[];
  plants: DispatchPlantRow[];
  kpis: {
    tripsCount: number;
    deliveredM3: number;
    inProgress: number;
    trucksAvailable: number;
  };
  serverNow: string;
}

export interface TripEventRow {
  id: number;
  trip_id: string;
  event: string;
  actor: string;
  reason: string;
  created_at: string;
}

const toTrip = (row: Row): DispatchTripRow => {
  const wait = numOrNull(row.wait_min_at_site) ?? numOrNull(row.site_wait_minutes);
  const departure = nullable(row.departure_time) ?? nullable(row.departed_at);
  const returned = nullable(row.return_time) ?? nullable(row.returned_at);
  const stage = nullable(row.stage_started_at);
  const stageElapsed =
    stage === null
      ? null
      : Math.max(0, Math.floor((Date.now() - new Date(stage).getTime()) / 60_000));
  const status = str(row.status) as DispatchTripStatus;
  return {
    id: str(row.id),
    company_id: str(row.company_id),
    plant_id: str(row.plant_id),
    order_id: nullable(row.order_id),
    customer_id: nullable(row.customer_id),
    truck_id: nullable(row.truck_id),
    driver_name: str(row.driver_name),
    mix_design_id: nullable(row.mix_design_id),
    target_m3: numOrNull(row.target_m3) ?? numOrNull(row.loaded_volume_m3) ?? 0,
    loaded_m3: numOrNull(row.loaded_m3) ?? numOrNull(row.loaded_volume_m3),
    status,
    departure_time: isoDateTime(departure),
    arrive_site_time: isoDateTime(row.arrive_site_time),
    finish_unload_time: isoDateTime(row.finish_unload_time),
    return_time: isoDateTime(returned),
    wait_min_at_site: wait,
    wait_flagged: isWaitFlagged(wait),
    cycle_minutes: cycleMinutes(departure, returned),
    site_wait_minutes: siteWaitMinutes(nullable(row.arrive_site_time), nullable(row.finish_unload_time)) ?? wait,
    stage_started_at: isoDateTime(stage),
    stage_elapsed_minutes: stageElapsed,
    cancel_reason: str(row.cancel_reason) || str(row.aborted_reason),
    trip_date: dateOnly(row.trip_date),
    created_at: isoDateTime(row.created_at) ?? '',
    order_no: str(row.order_no),
    concrete_grade: str(row.concrete_grade),
    order_status: str(row.order_status),
    customer_name_ar: str(row.customer_name_ar),
    customer_name_en: str(row.customer_name_en),
    project_name_ar: str(row.project_name_ar),
    project_name_en: str(row.project_name_en),
    truck_plate: str(row.truck_plate),
    truck_capacity_m3: numOrNull(row.truck_capacity_m3),
    mix_code: str(row.mix_code),
    mix_name_ar: str(row.mix_name_ar),
    mix_name_en: str(row.mix_name_en),
    group: tripGroup(status),
  };
};

const assertDate = (value: string): string => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value) || Number.isNaN(Date.parse(value))) {
    throw new M1Error('validation_error', 422, 'date must be YYYY-MM-DD', { field: 'date' });
  }
  return value;
};

const positive = (value: unknown, field: string): number => {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    throw new M1Error('validation_error', 422, `${field} must be greater than zero`, { field });
  }
  return parsed;
};

const required = (value: unknown, field: string): string => {
  const text = str(value).trim();
  if (!text) throw new M1Error('validation_error', 422, `${field} is required`, { field });
  return text;
};

export class DispatchService {
  constructor(private readonly db: Db) {}

  private level = (context: B1Context, min: number, what: string): void => {
    if (context.actor.roleLevel < min) {
      throw new M1Error('forbidden', 403, `only a level-${min} user may ${what}`);
    }
  };

  private plant = (context: B1Context, plantId: string): void => {
    const allowed = context.tenant.plantIds;
    if (allowed.length > 0 && !allowed.includes(plantId)) {
      throw new M1Error('forbidden_plant', 403, `plant ${plantId} is outside the caller's scope`);
    }
  };

  private withActor = <T>(context: B1Context, fn: (tx: Executor) => Promise<T>): Promise<T> =>
    this.db.withTenant(context.tenant, async (tx) => {
      await tx.unsafe(`select set_config('app.actor', $1, true)`, [context.actor.username]);
      return fn(tx);
    });

  private audit = async (
    tx: Executor,
    context: B1Context,
    action: string,
    tripId: string,
    plantId: string,
    details: Record<string, unknown>,
  ): Promise<void> => {
    await tx.unsafe(
      `insert into audit_log
         (company_id, plant_id, user_id, username, action, table_name, record_id, ip_address,
          request_id, details)
       values ($1,$2,$3,$4,$5,'trips',$6,$7,$8,$9::jsonb)`,
      [
        context.tenant.companyId,
        plantId,
        context.actor.userId,
        context.actor.username,
        action,
        tripId,
        context.actor.ip ?? null,
        context.actor.requestId ?? null,
        JSON.stringify(details),
      ],
    );
  };

  private readTrip = async (
    tx: Executor,
    context: B1Context,
    tripId: string,
  ): Promise<DispatchTripRow> => {
    const rows = await tx.unsafe<Row>(`${TRIP_SELECT} and tr.id = $2`, [
      context.tenant.companyId,
      tripId,
    ]);
    if (!rows[0]) throw new M1Error('trip_not_found', 404, `trip ${tripId} does not exist`);
    return toTrip(rows[0]);
  };

  private readTruckForUse = async (
    tx: Executor,
    context: B1Context,
    truckId: string,
    plantId: string,
  ): Promise<{ id: string; plate_no: string; capacity_m3: number }> => {
    const rows = await tx.unsafe<Row>(
      `select id, plant_id, plate_no, capacity_m3::text as capacity_m3, status, active
         from trucks
        where company_id = $1 and id = $2 and deleted_at is null
        for update`,
      [context.tenant.companyId, truckId],
    );
    const truck = rows[0];
    if (!truck || truck.active !== true) {
      throw new M1Error('truck_not_found', 404, `truck ${truckId} does not exist`);
    }
    if (str(truck.plant_id) !== plantId) {
      throw new M1Error('plant_mismatch', 422, 'truck and trip must belong to the same plant', {
        field: 'truckId',
      });
    }
    if (str(truck.status) === 'maintenance' || str(truck.status) === 'retired') {
      throw new M1Error('truck_unavailable', 409, `truck ${str(truck.plate_no)} is ${str(truck.status)}`);
    }
    const open = await tx.unsafe<{ n: number }>(
      `select count(*)::int as n from trips
        where company_id = $1 and truck_id = $2 and status = any($3::text[])`,
      [context.tenant.companyId, truckId, [...OPEN_TRIP_STATUSES]],
    );
    if ((open[0]?.n ?? 0) > 0) {
      throw new M1Error('truck_busy', 409, 'this truck already has an open trip', {
        check: 'openTrip',
        truckId,
      });
    }
    if (str(truck.status) !== 'available') {
      throw new M1Error('truck_busy', 409, `truck ${str(truck.plate_no)} is ${str(truck.status)}`);
    }
    return {
      id: str(truck.id),
      plate_no: str(truck.plate_no),
      capacity_m3: num(truck.capacity_m3),
    };
  };

  getBoard = async (
    context: B1Context,
    filters: { date?: string; plantId?: string } = {},
  ): Promise<DispatchBoard> => {
    this.level(context, 1, 'read the dispatch board');
    const date = filters.date ? assertDate(filters.date) : todayCairo();
    const plantId = filters.plantId?.trim() ?? '';
    if (plantId) this.plant(context, plantId);

    return this.withActor(context, async (tx) => {
      const tripsRaw = await tx.unsafe<Row>(
        `${TRIP_SELECT}
           and tr.trip_date = $2::date
           and ($3::text = '' or tr.plant_id = $3)
           and tr.status in ('queued', 'loading', 'loaded', 'traveling',
                             'unloading', 'unloaded', 'returned', 'cancelled')
         order by tr.created_at desc`,
        [context.tenant.companyId, date, plantId],
      );
      const trips = tripsRaw.map(toTrip);

      const trucksRaw = await tx.unsafe<Row>(
        `select t.id, t.plant_id, t.plate_no, t.capacity_m3::text as capacity_m3, t.status,
                t.odometer_km::text as odometer_km, t.active,
                (select count(*)::int from trips x
                  where x.company_id = t.company_id and x.truck_id = t.id
                    and x.trip_date = $2::date and x.status <> 'cancelled') as trips_today,
                (select coalesce(sum(coalesce(x.loaded_m3, x.loaded_volume_m3, 0)), 0)::text
                   from trips x
                  where x.company_id = t.company_id and x.truck_id = t.id
                    and x.trip_date = $2::date
                    and x.status in ('unloaded', 'returned')) as m3_today
           from trucks t
          where t.company_id = $1 and t.active and t.deleted_at is null
            and ($3::text = '' or t.plant_id = $3)
          order by t.plate_no`,
        [context.tenant.companyId, date, plantId],
      );
      const trucks: DispatchTruckRow[] = trucksRaw.map((row) => ({
        id: str(row.id),
        plant_id: str(row.plant_id),
        plate_no: str(row.plate_no),
        capacity_m3: num(row.capacity_m3),
        status: str(row.status),
        current_odometer: numOrNull(row.odometer_km),
        active: row.active === true,
        trips_today: num(row.trips_today),
        m3_today: num(row.m3_today),
      }));

      const ordersRaw = await tx.unsafe<Row>(
        `select o.id, o.plant_id, o.order_no, o.customer_id,
                c.name_ar as customer_name_ar, c.name_en as customer_name_en,
                o.project_id, p.name_ar as project_name_ar, p.name_en as project_name_en,
                o.concrete_grade, o.quantity_m3::text as quantity_m3, o.status,
                o.delivery_date, coalesce(o.order_date, o.created_at::date) as order_date,
                coalesce(sum(tr.target_m3), 0)::text as assigned_m3
           from orders o
           join customers c on c.id = o.customer_id and c.company_id = o.company_id
           left join projects p on p.id = o.project_id and p.company_id = o.company_id
           left join trips tr on tr.order_id = o.id and tr.company_id = o.company_id
                              and tr.status <> 'cancelled'
          where o.company_id = $1 and o.deleted_at is null
            and o.status in ('confirmed', 'scheduled', 'in_production')
            and ($2::text = '' or o.plant_id = $2)
          group by o.id, c.name_ar, c.name_en, p.name_ar, p.name_en
          order by o.delivery_date nulls last, o.order_no`,
        [context.tenant.companyId, plantId],
      );
      const orders: DispatchOrderRow[] = ordersRaw.map((row) => {
        const quantity = num(row.quantity_m3);
        const assigned = num(row.assigned_m3);
        return {
          id: str(row.id),
          plant_id: nullable(row.plant_id),
          order_no: str(row.order_no),
          customer_id: str(row.customer_id),
          customer_name_ar: str(row.customer_name_ar),
          customer_name_en: str(row.customer_name_en),
          project_id: nullable(row.project_id),
          project_name_ar: str(row.project_name_ar),
          project_name_en: str(row.project_name_en),
          concrete_grade: str(row.concrete_grade),
          quantity_m3: quantity,
          assigned_m3: assigned,
          remaining_m3: Math.max(0, quantity - assigned),
          status: str(row.status),
          delivery_date: dateOnly(row.delivery_date),
          order_date: dateOnly(row.order_date),
        };
      });

      const mixRaw = await tx.unsafe<Row>(
        `select id, plant_id, code, name_ar, name_en
           from mix_designs
          where company_id = $1 and ($2::text = '' or plant_id = $2)
          order by code`,
        [context.tenant.companyId, plantId],
      );
      const mixDesigns: DispatchMixRow[] = mixRaw.map((row) => ({
        id: str(row.id),
        plant_id: str(row.plant_id),
        code: str(row.code),
        name_ar: str(row.name_ar),
        name_en: str(row.name_en),
      }));

      const plantsRaw = await tx.unsafe<Row>(
        `select id, name_ar, name_en from plants
          where company_id = $1 and deleted_at is null order by name_en`,
        [context.tenant.companyId],
      );
      const plants: DispatchPlantRow[] = plantsRaw.map((row) => ({
        id: str(row.id),
        name_ar: str(row.name_ar),
        name_en: str(row.name_en),
      }));

      const kpis = dispatchKpis(
        trips,
        trucks.filter((truck) => truck.status === 'available').length,
      );
      return { date, trips, trucks, orders, mixDesigns, plants, kpis, serverNow: new Date().toISOString() };
    });
  };

  createTrip = async (
    context: B1Context,
    input: {
      orderId: string;
      truckId?: string;
      driverName: string;
      mixDesignId?: string;
      targetM3: number;
      plantId?: string;
      date?: string;
    },
  ): Promise<DispatchTripRow> => {
    this.level(context, 3, 'create a trip');
    const orderId = required(input.orderId, 'orderId');
    const driverName = required(input.driverName, 'driverName');
    const targetM3 = positive(input.targetM3, 'targetM3');
    const date = input.date ? assertDate(input.date) : todayCairo();
    const requestedTruck = input.truckId?.trim() || '';

    return this.withActor(context, async (tx) => {
      const orders = await tx.unsafe<Row>(
        `select o.id, o.plant_id, o.customer_id, o.order_no, o.concrete_grade, o.status,
                o.quantity_m3::text as quantity_m3,
                coalesce((select sum(x.target_m3) from trips x
                           where x.company_id = o.company_id and x.order_id = o.id
                             and x.status <> 'cancelled'), 0)::text as assigned_m3
           from orders o
          where o.company_id = $1 and o.id = $2 and o.deleted_at is null`,
        [context.tenant.companyId, orderId],
      );
      const order = orders[0];
      if (!order) throw new M1Error('order_not_found', 404, `order ${orderId} does not exist`);
      if (str(order.status) === 'closed' || str(order.status) === 'cancelled') {
        throw new M1Error('order_closed', 422, `order ${orderId} is ${str(order.status)}`, {
          orderStatus: str(order.status),
        });
      }
      if (!(ACCEPTED_ORDER_STATUSES as readonly string[]).includes(str(order.status))) {
        throw new M1Error('order_not_accepted', 422, `order ${orderId} is not accepted for dispatch`, {
          orderStatus: str(order.status),
        });
      }

      const quantity = num(order.quantity_m3);
      const assigned = num(order.assigned_m3);
      if (targetM3 > Math.max(0, quantity - assigned) + 0.000_1) {
        throw new M1Error('order_remaining_exceeded', 422, 'target exceeds the order remaining m³', {
          field: 'targetM3',
          remainingM3: Math.max(0, quantity - assigned),
        });
      }

      const orderPlant = nullable(order.plant_id);
      const plantId = input.plantId?.trim() || orderPlant || '';
      if (!plantId) {
        throw new M1Error('validation_error', 422, 'plantId is required when the order has no plant', {
          field: 'plantId',
        });
      }
      this.plant(context, plantId);
      if (orderPlant && orderPlant !== plantId) {
        throw new M1Error('plant_mismatch', 422, 'trip and order must belong to the same plant', {
          field: 'plantId',
        });
      }

      let truckId: string | null = null;
      if (requestedTruck) {
        const truck = await this.readTruckForUse(tx, context, requestedTruck, plantId);
        truckId = truck.id;
      }

      let mixDesignId: string | null = null;
      if (input.mixDesignId?.trim()) {
        const mix = await tx.unsafe<Row>(
          `select id, plant_id from mix_designs
            where company_id = $1 and id = $2`,
          [context.tenant.companyId, input.mixDesignId.trim()],
        );
        if (!mix[0]) throw new M1Error('mix_design_not_found', 422, 'mix design does not exist');
        if (str(mix[0].plant_id) !== plantId) {
          throw new M1Error('plant_mismatch', 422, 'mix design and trip must belong to the same plant');
        }
        mixDesignId = str(mix[0].id);
      }

      const id = newId('TRP');
      try {
        await tx.unsafe(
          `insert into trips (id, company_id, plant_id, order_id, customer_id, truck_id,
              driver_name, mix_design_id, target_m3, loaded_m3, status, trip_date,
              created_by, updated_by)
           values ($1,$2,$3,$4,$5,$6,$7,$8,$9,null,'queued',$10::date,$11,$11)`,
          [
            id,
            context.tenant.companyId,
            plantId,
            orderId,
            str(order.customer_id),
            truckId,
            driverName,
            mixDesignId,
            targetM3,
            date,
            context.actor.username,
          ],
        );
      } catch (error) {
        if (String(error).includes('trips_m11_open_per_truck_idx') || String(error).includes('duplicate key')) {
          throw new M1Error('truck_busy', 409, 'this truck already has an open trip', {
            check: 'openTrip',
          });
        }
        throw error;
      }

      if (truckId) {
        await tx.unsafe(
          `update trucks set status = 'on_trip', updated_by = $3
            where company_id = $1 and id = $2`,
          [context.tenant.companyId, truckId, context.actor.username],
        );
      }
      await this.audit(tx, context, 'trip.created', id, plantId, {
        orderId,
        truckId,
        targetM3,
        driverName,
      });
      return this.readTrip(tx, context, id);
    });
  };

  assignTruck = async (
    context: B1Context,
    tripId: string,
    truckId: string,
  ): Promise<DispatchTripRow> => {
    this.level(context, 3, 'assign a truck to a queued trip');
    const truck = required(truckId, 'truckId');
    return this.withActor(context, async (tx) => {
      const rows = await tx.unsafe<Row>(
        `select id, plant_id, status, truck_id from trips
          where company_id = $1 and id = $2 for update`,
        [context.tenant.companyId, tripId],
      );
      const trip = rows[0];
      if (!trip) throw new M1Error('trip_not_found', 404, `trip ${tripId} does not exist`);
      if (str(trip.status) !== 'queued') {
        throw new M1Error('invalid_transition', 409, 'a truck can only be assigned to a queued trip', {
          from: str(trip.status),
          to: 'queued',
        });
      }
      if (nullable(trip.truck_id)) {
        throw new M1Error('trip_already_assigned', 409, 'this trip already has a truck');
      }
      const usable = await this.readTruckForUse(tx, context, truck, str(trip.plant_id));
      await tx.unsafe(
        `update trips set truck_id = $3, updated_by = $4
          where company_id = $1 and id = $2`,
        [context.tenant.companyId, tripId, usable.id, context.actor.username],
      );
      await tx.unsafe(
        `update trucks set status = 'on_trip', updated_by = $3
          where company_id = $1 and id = $2`,
        [context.tenant.companyId, usable.id, context.actor.username],
      );
      await tx.unsafe(
        `insert into trip_events (company_id, plant_id, trip_id, event, actor, reason)
         values ($1,$2,$3,'truck_assigned',$4,'')`,
        [context.tenant.companyId, str(trip.plant_id), tripId, context.actor.username],
      );
      await this.audit(tx, context, 'trip.truck_assigned', tripId, str(trip.plant_id), {
        truckId: usable.id,
        plateNo: usable.plate_no,
      });
      return this.readTrip(tx, context, tripId);
    });
  };

  advanceTrip = async (
    context: B1Context,
    tripId: string,
    input: { loadedM3?: number | null } = {},
  ): Promise<DispatchTripRow> => {
    this.level(context, 3, 'advance a trip');
    return this.withActor(context, async (tx) => {
      const rows = await tx.unsafe<Row>(
        `select id, plant_id, status, truck_id from trips
          where company_id = $1 and id = $2 for update`,
        [context.tenant.companyId, tripId],
      );
      const trip = rows[0];
      if (!trip) throw new M1Error('trip_not_found', 404, `trip ${tripId} does not exist`);

      const current = str(trip.status) as DispatchTripStatus;
      const next = nextTripStatus(current);
      if (!next) {
        throw new M1Error('invalid_transition', 409, `trip ${tripId} is ${current}`, {
          from: current,
          to: '',
        });
      }

      const truckId = nullable(trip.truck_id);
      let loadedM3: number | null = null;
      let capacity: number | null = null;
      if (next === 'loading' && !truckId) {
        throw new M1Error('truck_required', 422, 'assign a truck before loading', {
          field: 'truckId',
        });
      }
      if (next === 'loaded') {
        if (!truckId) {
          throw new M1Error('truck_required', 422, 'assign a truck before loading', {
            field: 'truckId',
          });
        }
        loadedM3 = positive(input.loadedM3, 'loadedM3');
        const truckRows = await tx.unsafe<Row>(
          `select capacity_m3::text as capacity_m3 from trucks
            where company_id = $1 and id = $2`,
          [context.tenant.companyId, truckId],
        );
        capacity = numOrNull(truckRows[0]?.capacity_m3);
        if (capacity !== null && loadedM3 > capacity + 0.000_1) {
          throw new M1Error('capacity_exceeded', 422, 'the load exceeds the truck capacity', {
            check: 'capacity',
            capacityM3: capacity,
            loadedM3,
          });
        }
      }

      const stamp =
        next === 'traveling'
          ? ', departure_time = now()'
          : next === 'unloading'
            ? ', arrive_site_time = now()'
            : next === 'unloaded'
              ? `, finish_unload_time = now(),
                   wait_min_at_site = greatest(0,
                     floor(extract(epoch from (now() - coalesce(arrive_site_time, now()))) / 60)::int)`
              : next === 'returned'
                ? ', return_time = now()'
                : '';

      await tx.unsafe(
        `update trips
            set status = $3,
                loaded_m3 = case when $3 = 'loaded' then $4::numeric else loaded_m3 end
                ${stamp},
                updated_by = $5
          where company_id = $1 and id = $2`,
        [context.tenant.companyId, tripId, next, loadedM3, context.actor.username],
      );

      if (next === 'returned' && truckId) {
        await tx.unsafe(
          `update trucks set status = 'available', updated_by = $3
            where company_id = $1 and id = $2
              and status not in ('maintenance', 'retired')`,
          [context.tenant.companyId, truckId, context.actor.username],
        );
      }
      await this.audit(tx, context, `trip.${next}`, tripId, str(trip.plant_id), {
        from: current,
        to: next,
        loadedM3,
        capacityM3: capacity,
      });
      return this.readTrip(tx, context, tripId);
    });
  };

  cancelTrip = async (
    context: B1Context,
    tripId: string,
    reason: string,
  ): Promise<DispatchTripRow> => {
    this.level(context, 3, 'cancel a trip');
    if (reason.trim().length < MIN_OVERRIDE_REASON) {
      throw new M1Error(
        'validation_error',
        422,
        `reason must be at least ${MIN_OVERRIDE_REASON} characters`,
        { field: 'reason' },
      );
    }
    return this.withActor(context, async (tx) => {
      const rows = await tx.unsafe<Row>(
        `select id, plant_id, status, truck_id from trips
          where company_id = $1 and id = $2 for update`,
        [context.tenant.companyId, tripId],
      );
      const trip = rows[0];
      if (!trip) throw new M1Error('trip_not_found', 404, `trip ${tripId} does not exist`);
      if (isTerminalTripStatus(str(trip.status))) {
        throw new M1Error('invalid_transition', 409, `trip ${tripId} is ${str(trip.status)}`, {
          from: str(trip.status),
          to: 'cancelled',
        });
      }
      await tx.unsafe(
        `update trips set status = 'cancelled', cancel_reason = $3, updated_by = $4
          where company_id = $1 and id = $2`,
        [context.tenant.companyId, tripId, reason.trim(), context.actor.username],
      );
      if (nullable(trip.truck_id)) {
        await tx.unsafe(
          `update trucks set status = 'available', updated_by = $3
            where company_id = $1 and id = $2
              and status not in ('maintenance', 'retired')`,
          [context.tenant.companyId, nullable(trip.truck_id), context.actor.username],
        );
      }
      await this.audit(tx, context, 'trip.cancelled', tripId, str(trip.plant_id), {
        reason: reason.trim(),
      });
      return this.readTrip(tx, context, tripId);
    });
  };

  getTrip = async (context: B1Context, tripId: string): Promise<DispatchTripRow> => {
    this.level(context, 1, 'read a trip');
    return this.withActor(context, (tx) => this.readTrip(tx, context, tripId));
  };

  getTripEvents = async (context: B1Context, tripId: string): Promise<TripEventRow[]> => {
    this.level(context, 1, 'read trip events');
    return this.withActor(context, async (tx) => {
      await this.readTrip(tx, context, tripId);
      const rows = await tx.unsafe<Row>(
        `select id::text as id, trip_id, event, actor, reason, created_at
           from trip_events
          where company_id = $1 and trip_id = $2
          order by created_at, id`,
        [context.tenant.companyId, tripId],
      );
      return rows.map((row) => ({
        id: num(row.id),
        trip_id: str(row.trip_id),
        event: str(row.event),
        actor: str(row.actor),
        reason: str(row.reason),
        created_at: isoDateTime(row.created_at) ?? '',
      }));
    });
  };

  createTruck = async (
    context: B1Context,
    input: { plantId: string; plateNo: string; capacityM3: number; odometerKm?: number | null },
  ): Promise<DispatchTruckRow> => {
    this.level(context, 4, 'register a truck');
    const plantId = required(input.plantId, 'plantId');
    const plateNo = required(input.plateNo, 'plateNo');
    const capacityM3 = positive(input.capacityM3, 'capacityM3');
    this.plant(context, plantId);
    const id = newId('TRK');
    try {
      await this.withActor(context, async (tx) =>
        tx.unsafe(
          `insert into trucks (id, company_id, plant_id, plate_no, capacity_m3, status,
              odometer_km, active, created_by, updated_by)
           values ($1,$2,$3,$4,$5,'available',$6,true,$7,$7)`,
          [
            id,
            context.tenant.companyId,
            plantId,
            plateNo,
            capacityM3,
            input.odometerKm ?? null,
            context.actor.username,
          ],
        ),
      );
    } catch (error) {
      if (String(error).includes('duplicate key')) {
        throw new M1Error('duplicate_plate', 409, 'this plate is already registered in the company', {
          field: 'plateNo',
        });
      }
      throw error;
    }
    return this.readTruck(context, id);
  };

  private readTruck = async (context: B1Context, truckId: string): Promise<DispatchTruckRow> => {
    return this.withActor(context, async (tx) => {
      const rows = await tx.unsafe<Row>(
        `select id, plant_id, plate_no, capacity_m3::text as capacity_m3, status,
                odometer_km::text as odometer_km, active
           from trucks where company_id = $1 and id = $2 and deleted_at is null`,
        [context.tenant.companyId, truckId],
      );
      const row = rows[0];
      if (!row) throw new M1Error('truck_not_found', 404, `truck ${truckId} does not exist`);
      return {
        id: str(row.id),
        plant_id: str(row.plant_id),
        plate_no: str(row.plate_no),
        capacity_m3: num(row.capacity_m3),
        status: str(row.status),
        current_odometer: numOrNull(row.odometer_km),
        active: row.active === true,
        trips_today: 0,
        m3_today: 0,
      };
    });
  };

  updateTruckStatus = async (
    context: B1Context,
    truckId: string,
    status: string,
  ): Promise<DispatchTruckRow> => {
    this.level(context, 4, 'change a truck status');
    if (status !== 'available' && status !== 'maintenance') {
      throw new M1Error('validation_error', 422, 'status must be available or maintenance', {
        field: 'status',
      });
    }
    await this.withActor(context, async (tx) => {
      const rows = await tx.unsafe<Row>(
        `select id, plant_id, status from trucks
          where company_id = $1 and id = $2 and deleted_at is null for update`,
        [context.tenant.companyId, truckId],
      );
      const truck = rows[0];
      if (!truck) throw new M1Error('truck_not_found', 404, `truck ${truckId} does not exist`);
      const open = await tx.unsafe<{ n: number }>(
        `select count(*)::int as n from trips
          where company_id = $1 and truck_id = $2 and status = any($3::text[])`,
        [context.tenant.companyId, truckId, [...OPEN_TRIP_STATUSES]],
      );
      if ((open[0]?.n ?? 0) > 0) {
        throw new M1Error('truck_has_open_trip', 409, 'the truck still has an open trip');
      }
      await tx.unsafe(
        `update trucks set status = $3, updated_by = $4
          where company_id = $1 and id = $2`,
        [context.tenant.companyId, truckId, status, context.actor.username],
      );
      await tx.unsafe(
        `insert into audit_log
           (company_id, plant_id, user_id, username, action, table_name, record_id, ip_address,
            request_id, details)
         values ($1,$2,$3,$4,'truck.status_changed','trucks',$5,$6,$7,$8::jsonb)`,
        [
          context.tenant.companyId,
          str(truck.plant_id),
          context.actor.userId,
          context.actor.username,
          truckId,
          context.actor.ip ?? null,
          context.actor.requestId ?? null,
          JSON.stringify({ from: str(truck.status), to: status }),
        ],
      );
    });
    return this.readTruck(context, truckId);
  };
}
